        bestd = None
        for (rx, ry) in res:
            d = abs(rx - sx) + abs(ry - sy)
            if bestd is None or d < bestd:
                bestd = d
                best = (rx, ry)
        tx, ty = best
    else:
        tx, ty = ox, oy

    best_move = (0, 0)
    best_score = None

    for dx, dy in moves:
